import app from 'flarum/admin/app';
import FormModal from 'flarum/common/components/FormModal';
import Form from 'flarum/common/components/Form';
import FormGroup from 'flarum/common/components/FormGroup';
import Stream from 'flarum/common/utils/Stream';
import ItemList from 'flarum/common/utils/ItemList';
import Button from 'flarum/common/components/Button';
import purgeLSCache from '../../common/purgeLSCache';
export default class PurgeLSCacheModal extends FormModal {
  purgeType = Stream('all');
  purgePaths = Stream('');
  purgeTags = Stream('');
  className() {
    return 'PurgeLSCacheModal';
  }
  title() {
    return app.translator.trans('acpl-lscache.admin.purge_modal.title');
  }
  content() {
    return m(Form, {
      className: "Modal-body"
    }, this.items().toArray(), m("div", {
      className: "Form-group Form-controls"
    }, m(Button, {
      className: "Button Button--primary",
      type: "submit",
      disabled: this.loading,
      loading: this.loading
    }, app.translator.trans('acpl-lscache.admin.purge_modal.submit_button'))));
  }
  items() {
    const itemList = new ItemList();
    const purgeType = this.purgeType();
    itemList.add('type', m(FormGroup, {
      type: "radio",
      stream: this.purgeType,
      label: app.translator.trans('acpl-lscache.admin.purge_modal.type_label'),
      options: [{
        value: 'all',
        label: app.translator.trans('acpl-lscache.admin.purge_modal.all_label')
      }, {
        value: 'paths',
        label: app.translator.trans('acpl-lscache.admin.purge_modal.paths_label')
      }, {
        value: 'tags',
        label: app.translator.trans('acpl-lscache.admin.purge_modal.tags_label')
      }],
      required: true
    }));
    if (purgeType === 'paths') {
      itemList.add('paths', m(FormGroup, {
        type: "textarea",
        stream: this.purgePaths,
        label: app.translator.trans(`acpl-lscache.admin.purge_modal.paths_label`),
        help: app.translator.trans(`acpl-lscache.admin.purge_modal.paths_help`, {
          url: app.forum.attribute('baseUrl')
        }),
        placeholder: "/t/general",
        required: true
      }));
    } else if (purgeType === 'tags') {
      itemList.add('tags', m(FormGroup, {
        type: "textarea",
        stream: this.purgeTags,
        label: app.translator.trans(`acpl-lscache.admin.purge_modal.tags_label`),
        help: app.translator.trans(`acpl-lscache.admin.purge_modal.tags_help`),
        placeholder: "discussion_123",
        required: true
      }));
    }
    return itemList;
  }
  onsubmit(e) {
    e.preventDefault();
    if (this.loading) return;
    const purgeType = this.purgeType();
    const params = {};
    if (purgeType !== 'all') {
      const stream = purgeType === 'paths' ? this.purgePaths : this.purgeTags;
      const items = this.parsePurgeList(stream());
      if (!items.length) {
        app.alerts.show({
          type: 'error'
        }, app.translator.trans('acpl-lscache.admin.purge_modal.empty_list_error'));
        return;
      }
      params[purgeType] = items;
    }
    this.loading = true;
    purgeLSCache(params).then(() => this.hide()).catch(error => this.onerror(error)).finally(() => this.loaded());
  }
  parsePurgeList(value) {
    return value.split('\n').map(item => item.trim()).filter(item => item.length > 0);
  }
}
flarum.reg.add('acpl-lscache', 'admin/components/PurgeLSCacheModal', PurgeLSCacheModal);